<dialog id="product-dialog"><form id="product-form" action="/products" method="post">@csrf<input name="_method" value="POST" type="hidden"><div class="dialog-head"><h2 id="product-title">Nuevo producto</h2><button type="button" onclick="this.closest('dialog').close()" aria-label="Cerrar">×</button></div><p class="muted">Define el producto. Luego agrega stock mediante una entrada.</p><div class="form-grid"><label>Nombre<input required name="name" maxlength="150" value="{{ old('name') }}"></label><label>Código SKU<input required name="sku" maxlength="60" value="{{ old('sku') }}"></label><label>Categoría<input required name="category" list="categories" value="{{ old('category') }}"><datalist id="categories">@foreach($categories as $c)<option value="{{ $c }}">@endforeach</datalist></label><label>Stock mínimo<input required name="minimum" type="number" min="0" value="{{ old('minimum',5) }}"></label><label>Costo unitario (CLP)<input required name="cost" type="number" min="0" step="0.01" value="{{ old('cost',0) }}"></label><label>Descripción<input name="description" value="{{ old('description') }}"></label></div><div class="dialog-actions"><button type="button" onclick="this.closest('dialog').close()">Cancelar</button><button class="primary">Guardar producto</button></div></form></dialog>
<dialog id="movement-dialog"><form action="/movements" method="post">@csrf<div class="dialog-head"><h2>Registrar movimiento</h2><button type="button" onclick="this.closest('dialog').close()" aria-label="Cerrar">×</button></div><p class="muted">El movimiento quedará registrado y actualizará las existencias.</p><div class="form-grid"><label>Producto<select required name="product_id"><option value="">Seleccionar producto</option>@foreach($all as $p)<option value="{{ $p->id }}" @selected(old('product_id')==$p->id)>{{ $p->name }} · {{ $p->sku }}</option>@endforeach</select></label><label>Tipo<select name="type" id="movement-type" onchange="updateMovement()">@foreach(['entrada','traslado','salida'] as $t)<option value="{{ $t }}" @selected(old('type')===$t)>{{ ucfirst($t) }}</option>@endforeach</select></label><label id="from-label">Origen<select name="from_id"><option value="">Seleccionar origen</option>@foreach($locations as $l)<option value="{{ $l->id }}" @selected(old('from_id')==$l->id)>{{ $l->name }}</option>@endforeach</select></label><label id="to-label">Destino<select name="to_id"><option value="">Seleccionar destino</option>@foreach($locations as $l)<option value="{{ $l->id }}" @selected(old('to_id')==$l->id)>{{ $l->name }}</option>@endforeach</select></label><label>Cantidad<input name="quantity" type="number" required min="1" max="1000000" value="{{ old('quantity',1) }}"></label><label>Fecha y hora<input type="datetime-local" name="occurred_at" required value="{{ old('occurred_at',now()->format('Y-m-d\TH:i')) }}"></label><label>Responsable<input name="responsible" required maxlength="100" value="{{ old('responsible') }}" placeholder="Nombre de quien realiza el movimiento"></label><label>Motivo / Nota<input name="note" value="{{ old('note') }}" placeholder="Ej. Asignación al área de soporte"></label></div><div class="dialog-actions"><button type="button" onclick="this.closest('dialog').close()">Cancelar</button><button class="primary">Registrar movimiento</button></div></form></dialog>
